package com.mentality.forgewebmap.render;
import net.minecraft.core.BlockPos;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.Blocks;import net.minecraft.world.level.chunk.LevelChunk;import net.minecraft.world.level.levelgen.Heightmap;
/** Selects a playable Nether cavern surface below the bedrock roof. */
public final class SurfaceHeightResolver {public int resolve(ServerLevel l,int x,int z){int s=Math.max(l.getMinBuildHeight(),l.getHeight(Heightmap.Types.WORLD_SURFACE,x,z)-1);return selectSurface(l.dimension().equals(Level.NETHER),l.getMinBuildHeight(),s,l.getMaxBuildHeight()-6,y->l.getBlockState(new BlockPos(x,y,z)).is(Blocks.BEDROCK),y->l.getBlockState(new BlockPos(x,y,z)).isAir());}public int resolve(ServerLevel l,LevelChunk c,int x,int z){int s=Math.max(l.getMinBuildHeight(),c.getHeight(Heightmap.Types.WORLD_SURFACE,x&15,z&15)-1);return selectSurface(l.dimension().equals(Level.NETHER),l.getMinBuildHeight(),s,l.getMaxBuildHeight()-6,y->c.getBlockState(new BlockPos(x,y,z)).is(Blocks.BEDROCK),y->c.getBlockState(new BlockPos(x,y,z)).isAir());}static int selectSurface(boolean nether,int min,int surface,int top,java.util.function.IntPredicate bedrock,java.util.function.IntPredicate air){return nether?selectNetherSurface(min,top,bedrock,air,surface):surface;}static int selectNetherSurface(int min,int top,java.util.function.IntPredicate bedrock,java.util.function.IntPredicate air,int fallback){for(int y=top;y>=min;y--)if(!bedrock.test(y)&&!air.test(y))return y;return fallback;}}
